    // Perform Gauss–Jordan elimination
    for i in 0..n {
        // 1) Find pivot row (max absolute value in column i from rows i..n)
        let mut pivot = i;
        let mut max_val = aug[i][i].abs();
        for r in (i + 1)..n {
            let v = aug[r][i].abs();
            if v > max_val {
                max_val = v;
                pivot = r;
            }
        }
        // 2) Swap current row with pivot row
        if pivot != i {
            aug.swap(i, pivot);
        }
        // 3) Normalize pivot row
        let diag = aug[i][i];
        assert!(diag != 0.0, "Matrix is singular or nearly singular");
        for c in i..=n {
            aug[i][c] /= diag;
        }
        // 4) Eliminate column i in all other rows
        for r in 0..n {
            if r != i {
                let factor = aug[r][i];
                for c in i..=n {
                    aug[r][c] -= factor * aug[i][c];
                }
            }
        }
    }

    // Extract solution vector from last column of the augmented matrix
    let mut x = vec![0.0; n];
